#!/usr/bin/env bash
# Régénère les polices de main/fonts/ (lv_font_conv, npm i -g lv_font_conv).
# LVGL_DIR = clone de lvgl v9.2.2 (contient scripts/built_in_font/).
set -euo pipefail
LVGL_DIR=${LVGL_DIR:?chemin vers lvgl}
cd "$(dirname "$0")/../main/fonts"
lv_font_conv --no-compress --no-prefilter --bpp 4 --size 44 --font "$LVGL_DIR"/scripts/built_in_font/Montserrat-Medium.ttf -r 0x20,0x25,0x2B-0x3A --format lvgl --lv-include lvgl.h --lv-font-name font_num_44 -o font_num_44.c
lv_font_conv --no-compress --no-prefilter --bpp 4 --size 11 --font "$LVGL_DIR"/scripts/built_in_font/Montserrat-Medium.ttf -r 0x20-0x7E,0xA0-0xFF,0x2019,0x2026 --format lvgl --lv-include lvgl.h --lv-font-name font_small_11 -o font_small_11.c
lv_font_conv --no-compress --no-prefilter --bpp 4 --size 16 --font "$LVGL_DIR"/scripts/built_in_font/Montserrat-Medium.ttf -r 0x20-0x7E,0xA0-0xFF,0x152-0x153,0x178,0x2013-0x2014,0x2018-0x2019,0x201C-0x201E,0x2022,0x2026,0x20AC --font "$LVGL_DIR"/scripts/built_in_font/FontAwesome5-Solid+Brands+Regular.woff -r 0xF001,0xF00B,0xF00C,0xF00D,0xF011,0xF013,0xF015,0xF021,0xF053,0xF054,0xF077,0xF078,0xF0E7,0xF0F3,0xF1F6,0xF240,0xF241,0xF242,0xF243,0xF244,0xF293,0xF2ED,0xF0E0,0xF095,0xF086,0xF048,0xF04B,0xF04C,0xF051,0xF027,0xF028,0xF06E,0xF2F2,0xF252,0xF0EB,0xF186,0xF1DE,0xF00A,0xF04D,0xF26C --format lvgl --lv-include lvgl.h --lv-font-name font_text_16 -o font_text_16.c
lv_font_conv --no-compress --no-prefilter --bpp 4 --size 72 --font "$LVGL_DIR"/scripts/built_in_font/Montserrat-Medium.ttf -r 0x30-0x3A --format lvgl --lv-include lvgl.h --lv-font-name font_time_72 -o font_time_72.c
lv_font_conv --no-compress --no-prefilter --bpp 4 --size 20 --font "$LVGL_DIR"/scripts/built_in_font/Montserrat-Medium.ttf -r 0x20-0x7E,0xA0-0xFF,0x152-0x153,0x178,0x2013-0x2014,0x2018-0x2019,0x201C-0x201E,0x2022,0x2026,0x20AC --font "$LVGL_DIR"/scripts/built_in_font/FontAwesome5-Solid+Brands+Regular.woff -r 0xF001,0xF00B,0xF00C,0xF00D,0xF011,0xF013,0xF015,0xF021,0xF053,0xF054,0xF077,0xF078,0xF0E7,0xF0F3,0xF1F6,0xF240,0xF241,0xF242,0xF243,0xF244,0xF293,0xF2ED,0xF0E0,0xF095,0xF086,0xF048,0xF04B,0xF04C,0xF051,0xF027,0xF028,0xF06E,0xF2F2,0xF252,0xF0EB,0xF186,0xF1DE,0xF00A,0xF04D,0xF26C --format lvgl --lv-include lvgl.h --lv-font-name font_title_20 -o font_title_20.c
